fn numpy_where(condition: Vec<bool>, x: Vec<f32>, y: Vec<f32>) -> Vec<f32> {
    // Ensure all input vectors have the same length
    assert_eq!(condition.len(), x.len(), "Condition and x must have the same length");
    assert_eq!(condition.len(), y.len(), "Condition and y must have the same length");

    // Create a new vector to hold the results
    let mut result = Vec::with_capacity(condition.len());

    // Iterate through the indices of the input vectors
    for i in 0..condition.len() {
        if condition[i] {
            result.push(x[i]); // Take from x if condition is true
        } else {
            result.push(y[i]); // Take from y if condition is false
        }
    }

    result // Return the resulting vector
}